const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeTuzPoint = ee.Geometry.Point(33.42, 38.78);
  const region = lakeTuzPoint.buffer(80000); // 80 km buffer to cover Lake Tuz

  const date1988_start = '1988-08-01';
  const date1988_end = '1988-08-31';
  const date2016_start = '2016-08-01';
  const date2016_end = '2016-08-31';

  const scale = 30; // Landsat resolution

  // Function to mask clouds for Landsat 5/7/8 SR data
  function maskL8sr(image) {
    // Bits 3 and 5 are cloud and cloud shadow, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Get the QA band.
    const qa = image.select('pixel_qa');
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    // Apply the scaling factors to the appropriate bands.
    const opticalBands = image.select('B.*').multiply(0.0000275).add(-0.2);
    // Return the masked image with scaled surface reflectance bands.
    return image.addBands(opticalBands, null, true).updateMask(mask);
  }

  // Function to calculate NDWI and create a water mask
  function calculateWaterMask(image, greenBand, nirBand) {
    const ndwi = image.normalizedDifference([greenBand, nirBand]).rename('NDWI');
    // A common threshold for water is NDWI > 0.
    const waterMask = ndwi.gt(0).rename('water');
    return image.addBands(waterMask);
  }

  // Function to process a collection for water area
  async function processCollection(collectionName, startDate, endDate, region, greenBand, nirBand, label) {
    let collection = ee.ImageCollection(collectionName)
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .map(maskL8sr);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`${label} Images: 0`);
      return { area: null, count: 0 };
    }

    // Sort by cloud cover and take the least cloudy image, or a median composite
    // For water area, a median composite is often more robust
    const medianImage = collection.median();

    // Calculate water mask
    const imageWithWaterMask = calculateWaterMask(medianImage, greenBand, nirBand);

    // Calculate water area
    const waterAreaSqM = imageWithWaterMask.select('water')
      .multiply(ee.Image.pixelArea())
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      });

    const area = waterAreaSqM.get('water').getInfo();

    // Check pixel count for validation
    const pixelCount = imageWithWaterMask.select('water')
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('water').getInfo();

    const cloudPercentage = collection.aggregate_mean('CLOUD_COVER').getInfo();
    console.log(`${label} Images: ${collectionSize} (Cloud: ${cloudPercentage !== null ? cloudPercentage.toFixed(2) : 'N/A'}%)`);

    if (pixelCount === 0 || area === 0) {
      console.log(`${label} No valid water pixels found after processing.`);
      return { area: 0, count: pixelCount }; // Return 0 if no water, not C2 unless general valid pixels are 0
    }

    return { area: area, count: pixelCount };
  }

  // 2. Data Acquisition & Processing for 1988
  let result1988;
  try {
    result1988 = await processCollection(
      'LANDSAT/LT05/C01/T1_SR',
      date1988_start, date1988_end, region,
      'B2', 'B4', '1988'
    );
  } catch (e) {
    console.log(`Error processing 1988 data: ${e}`);
    console.log('C3');
    return;
  }

  if (result1988.count === 0 && result1988.area === null) {
    console.log('C1');
    return;
  }
  if (result1988.count === 0 && result1988.area === 0) {
    // Special case: Images exist, but no water pixels. Still a valid result for comparison.
  }

  // 2. Data Acquisition & Processing for 2016
  let result2016;
  try {
    result2016 = await processCollection(
      'LANDSAT/LC08/C01/T1_SR',
      date2016_start, date2016_end, region,
      'B3', 'B5', '2016'
    );
  } catch (e) {
    console.log(`Error processing 2016 data: ${e}`);
    console.log('C3');
    return;
  }

  if (result2016.count === 0 && result2016.area === null) {
    console.log('C1');
    return;
  }
  if (result2016.count === 0 && result2016.area === 0) {
    // Special case: Images exist, but no water pixels. Still a valid result for comparison.
  }

  // 4. Calculation & Validation
  const area1988 = result1988.area;
  const area2016 = result2016.area;

  if (area1988 === null || area2016 === null) {
    // This condition should be caught by C1 above, but as a safeguard
    console.log('C3');
    return;
  }

  console.log(`Lake Tuz Water Area 1988: ${(area1988 / 1e6).toFixed(2)} sq km (Pixels: ${result1988.count})`);
  console.log(`Lake Tuz Water Area 2016: ${(area2016 / 1e6).toFixed(2)} sq km (Pixels: ${result2016.count})`);

  if (area2016 < area1988) {
    console.log('A'); // Yes, it decreased
  } else {
    console.log('B'); // No, it did not decrease (stayed same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
